// CSD_RATIONALE_BEGIN
// Root-cause analysis from prior attempts:
//
// Attempt 1 (best: 40.8%): Per-step IsCompletePrefix + CloseConstrainedSpan +
// AdaptiveConstrainedStep. Closes spans immediately on first complete parse,
// preventing the /1/1/1 repetition loops seen in attempt 72's CloseSpanWithinBudget.
// Bug: used `next == "<<"` (exact token equality) which is explicitly forbidden
// and may miss spans when the tokenizer emits `" <<"` or splits the delimiter.
//
// Attempt 72 (12.2%): CloseSpanWithinBudget(50) → tracks longest complete prefix,
// which selects `x * k / 1 / 1 / 1` over shorter `x * k`, causing repetition.
//
// This attempt builds directly on attempt 1 with three targeted fixes:
// 1. Replace `next == "<<"` with `RenderedEndsWith(generated, "<<")` to correctly
//    detect span entry even when the delimiter is split or space-prefixed.
// 2. Improve task guidance with concrete Python expression examples to discourage
//    redundant-term generation (* 1, / 1, + 0 patterns).
// 3. Keep the proven structure: immediate close on IsCompletePrefix, then
//    AdaptiveConstrainedStep inside spans, budget-pressure CloseSpanWithinBudget
//    as a safety net for unclosed final spans.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span / not-inside branch (OpenConstrainedSpan):
//     Sets insideConstrainedOut := true and currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by method precondition `parser.IsValidPrefix([])`. ✓
//
//   Outside-span (UnconstrainedStep, non-EOS, no << detected):
//     insideConstrainedOut remains false; implication is vacuous. ✓
//
//   Outside-span (RenderedEndsWith fires → EnterObservedConstrainedSpan):
//     Sets currentConstrainedOut := []; parser.IsValidPrefix([]) holds. ✓
//
//   Inside-span (CloseConstrainedSpan path):
//     Sets insideConstrainedOut := false; implication becomes vacuously true;
//     helper postcondition also gives currentConstrainedOut := []. ✓
//
//   Inside-span (CloseSpanWithinBudget path):
//     Helper postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   Inside-span (AdaptiveConstrainedStep + AppendConstrainedToken path):
//     AdaptiveConstrainedStep returns a parser-valid next token (or EOS).
//     AppendConstrainedToken postcondition guarantees that appending that valid
//     token preserves parser.IsValidPrefix on the extended currentConstrainedOut. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: |generatedPrefix| == |generatedPrefix| + 0. ✓
//
//   OpenConstrainedSpan branch: steps += 1, generated gains exactly one `<<` token;
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + (steps-1) + 1
//     = |generatedPrefix| + steps. ✓
//
//   UnconstrainedStep, non-EOS: steps += 1, generated gains one token; same bound. ✓
//   UnconstrainedStep, EOS: steps += 1, generated unchanged; bound preserved. ✓
//
//   CloseConstrainedSpan: steps += 1, generated gains at most one `>>` token; ✓
//
//   CloseSpanWithinBudget: closeBudget = maxSteps - steps; helper postcondition
//     gives |cg| <= |generated| + closeBudget = |generated| + (maxSteps - steps);
//     after steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps = 
//     |generatedPrefix| + steps. ✓
//
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1 before append;
//     AppendConstrainedToken grows generated by exactly one token;
//     |generated|_new = |generated|_old + 1 <= |generatedPrefix| + (steps-1) + 1
//     = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. For each intermediate calculation and for the final answer, write exactly one direct Python expression inside << >> delimiters. Use the variable names from the problem directly. Keep each expression minimal—no redundant * 1, / 1, or + 0 terms. Examples: <<x * k>>, <<a + b - c>>, <<int(n * r)>>, <<n * (r + 1) ** d>>, <<first_hour_cost + (hours - 1) * first_hour_cost * multiplier>>.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    // Budget pressure: force open a constrained span to capture the final answer.
    if maxSteps - steps <= 3 && steps > 0 {
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        // Use RenderedEndsWith to correctly detect << even when split or space-prefixed.
        if RenderedEndsWith(generated, "<<") {
          var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
          generated := eg;
          insideConstrainedOut := ei;
          currentConstrainedOut := ec;
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Close immediately at the first complete parse to prevent runaway extension.
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 2 {
      // Near budget end: use CloseSpanWithinBudget as a safety net.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: advance one parser-valid token.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

